import type { TopologyCameraState } from "./TopologyViewportController.ts";
import type {
  TopologyRenderFrame,
  TopologyRenderOccupant,
  TopologyRenderRelationship,
} from "./renderPipeline.ts";

export interface TopologyDeveloperSceneAdapter {
  id: string;
  entities(): TopologyRenderOccupant[];
  relationships(): TopologyRenderRelationship[];
  cells(): TopologyRenderFrame["cells"];
  frame(): TopologyRenderFrame;
  selected(): string | null;
  inspect(entityId: string): void;
  highlight(q: number, r: number): boolean;
  clearHighlights(): void;
  broadcast(entityId: string): boolean;
  path(fromId: string, toId: string): boolean;
  stopSignals(): void;
}

export interface TopologyDeveloperCameraAdapter {
  get(): TopologyCameraState;
  fit(): void;
  center(): void;
  focus(entityId: string): boolean;
  zoom(value: number): void;
  reset(): void;
}

interface DeveloperSceneRegistration {
  scene?: TopologyDeveloperSceneAdapter;
  camera?: TopologyDeveloperCameraAdapter;
}

const registrations = new Map<string, DeveloperSceneRegistration>();
let activeSceneId = "";
let sceneCounter = 0;

export function ensureDeveloperSceneId(scene: HTMLElement) {
  if (!scene.dataset.topologySceneId) {
    sceneCounter += 1;
    scene.dataset.topologySceneId = scene.id || `topology-scene-${sceneCounter}`;
  }
  return scene.dataset.topologySceneId;
}

function registrationFor(sceneId: string) {
  const registration = registrations.get(sceneId) ?? {};
  registrations.set(sceneId, registration);
  activeSceneId = sceneId;
  return registration;
}

export function registerDeveloperScene(adapter: TopologyDeveloperSceneAdapter) {
  const registration = registrationFor(adapter.id);
  registration.scene = adapter;

  return () => {
    const current = registrations.get(adapter.id);
    if (!current || current.scene !== adapter) return;
    delete current.scene;
    if (!current.camera) registrations.delete(adapter.id);
  };
}

export function registerDeveloperCamera(
  sceneId: string,
  adapter: TopologyDeveloperCameraAdapter,
) {
  const registration = registrationFor(sceneId);
  registration.camera = adapter;

  return () => {
    const current = registrations.get(sceneId);
    if (!current || current.camera !== adapter) return;
    delete current.camera;
    if (!current.scene) registrations.delete(sceneId);
  };
}

export function listDeveloperScenes() {
  return [...registrations.entries()]
    .filter(([, registration]) => Boolean(registration.scene))
    .map(([id]) => id);
}

export function useDeveloperScene(sceneId: string) {
  if (!registrations.get(sceneId)?.scene) return false;
  activeSceneId = sceneId;
  return true;
}

export function getActiveDeveloperRegistration() {
  if (activeSceneId && registrations.get(activeSceneId)?.scene) {
    return { id: activeSceneId, ...registrations.get(activeSceneId) };
  }

  const fallback = [...registrations.entries()].find(([, registration]) => registration.scene);
  if (!fallback) return null;
  activeSceneId = fallback[0];
  return { id: fallback[0], ...fallback[1] };
}

export function clearDeveloperRegistrations() {
  registrations.clear();
  activeSceneId = "";
}
